// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _test(uint256 _val1, uint256 _val2) internal {
        vm.assume(_val1 != _val2);
        try c.SetMinSum(_val1) {} catch { return; }
        try c.Initialized() {} catch { return; }
        uint256 pre;
        try c.MinSum() returns (uint256 __r) { pre = __r; } catch { return; }
        try c.SetMinSum(_val2) {} catch { return; }
        uint256 post;
        try c.MinSum() returns (uint256 __r) { post = __r; } catch { return; }
        assertTrue(post == pre);
    }

    function testFuzz_test(uint256 _val1, uint256 _val2) public {
        _test(_val1, _val2);
    }

    receive() external payable {}
}
